// Read-only status board. Shows project/progress.md as captured in planning-data.json
// (generated by scripts/build-planning.mjs). No backend, no writes.

const COLUMNS = [
    { id: "done", label: "Klart" },
    { id: "in_progress", label: "Pågår" },
    { id: "pending", label: "Väntar" },
];

function renderCard(item) {
    const li = document.createElement("li");
    li.className = "kanban-card";

    const label = document.createElement("span");
    label.className = "feature-label";
    label.textContent = item.featureId;

    const title = document.createElement("p");
    title.className = "kanban-card-title";
    title.textContent = `Fas ${item.phase}${item.scope ? ` · ${item.scope}` : ""}`;

    const status = document.createElement("p");
    status.className = "kanban-card-meta";
    status.textContent = `Status: ${item.statusText}`;

    li.append(label, title, status);

    if (item.note) {
        const note = document.createElement("p");
        note.className = "kanban-card-meta";
        note.textContent = item.note;
        li.append(note);
    }
    return li;
}

function renderBoard(features) {
    for (const column of COLUMNS) {
        const list = document.querySelector(`.kanban-list[data-column="${column.id}"]`);
        const items = features
            .filter((f) => f.status === column.id)
            .sort((a, b) => a.phase - b.phase);

        list.replaceChildren(...items.map(renderCard));
        document.querySelector(`[data-count="${column.id}"]`).textContent = `(${items.length})`;
        if (items.length === 0) {
            const empty = document.createElement("li");
            empty.className = "kanban-empty";
            empty.textContent = "Inga uppgifter";
            list.append(empty);
        }
    }
}

function setStatus(text) {
    document.getElementById("planningStatus").textContent = text;
}

async function loadPlanning() {
    try {
        const response = await fetch("planning-data.json", { cache: "no-store" });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = await response.json();

        renderBoard(data.features);
        setStatus(`Status enligt ${data.source}, senast uppdaterad ${data.lastUpdated}. ${data.features.length} poster.`);
    } catch (err) {
        console.error(err);
        setStatus("Kunde inte läsa statusfilen (planning-data.json).");
    }
}

loadPlanning();
